CREATE PROCEDURE [dbo].[SP_S_SavetEMPLATEPermission] @XMLDetails AS XML ,@ModuleTypeID INT
AS  
    DECLARE @iDocID INT 
    BEGIN
       BEGIN TRY
         BEGIN TRANSACTION
		  EXEC sp_xml_preparedocument @iDocID OUTPUT, @XMLDetails;
		  DECLARE @TemplateId INT,@Count INT =0,@UserId INT,@TemplateName VARCHAR(MAX),@DetailID INT,@FormID INT,@moduleID INT,@ViewAccess INT,@InsertAccess INT,@UpdateAccess INT,@DeleteAccess INT,@PrintAccess INT,@IPAddress VARCHAR(MAX)--,@CreatedUserID int

				SELECT  *
				INTO    #TEMPH
				FROM    OPENXML (@iDocID,'SecurityTemplateVM',2)	
				WITH (Id INT , TemplateID INT,UserId INT,IPAddress VARCHAR(MAX))
				SELECT TOP(1) @TemplateId=TemplateID,@UserId=UserId,@IPAddress = IPAddress
				FROM #TempH

				--select * from #TEMPH
			   
				--select 1 as 'UserMa5sterID'
				SELECT *
				INTO #TempD
				FROM    OPENXML (@iDocID,'SecurityTemplateVM/UserWisePermisionVM/UserWisePermisionVM',2)
				WITH (FormId INT,ViewAccess BIT,InsertAccess BIT,UpdateAccess BIT,DeleteAccess BIT,PrintAccess BIT)
				
			SELECT * FROM #TempD

				CREATE TABLE #TempC(
				FormId INT,UserID INT,ViewAccess BIT,InsertAccess BIT,UpdateAccess BIT,DeleteAccess BIT,PrintAccess BIT,TemplateID INT
				)

				--INSERT INTO #TempC
				--(
				--    FormId,
				--    UserID,
				--    ViewAccess,
				--    InsertAccess,
				--    UpdateAccess,
				--    DeleteAccess,
				--    PrintAccess,
				--	TemplateID
				--)
				
				if(@ModuleTypeID = 3000)
				BEGIN
				delete from AutoGenerateGroupPrivileges
				where UserGroupID= @TemplateId and FormID > 3000  
				END
				ELSE
				BEGIN
				delete from AutoGenerateGroupPrivileges
				where UserGroupID= @TemplateId and FormID < 3000  
				END

				insert into AutoGenerateGroupPrivileges
				( UserGroupID, AutoGenerateID, FormID, ModuleID, DefaultViewAccess, DefaultInsertAccess, DefaultModifyAccess, 
				DefaultDeleteAccess, DefaultPrintAccess,CreatedDate,LastModDate,CreatedUserID,LastModUserID,HasBrekdown )
				SELECT @TemplateId,1,d.FormId,f.ModuleType ,d.ViewAccess,d.InsertAccess,d.UpdateAccess,d.DeleteAccess,d.PrintAccess, getdate(),
				getdate(),@userID, @UserID,0
				--FormId,@UserId,ViewAccess,InsertAccess,UpdateAccess,DeleteAccess,PrintAccess,@TemplateId
				FROM #TempD d inner join AutoGenerateInfoes f on d.formid= f.FormId
				
				--select * from #TempD
				--select * from #TempH

				
				--UPDATE dbo.AutoGenerateTemplates SET IPAddress = @IPAddress, DefaultViewAccess= T.ViewAccess, DefaultInsertAccess = T.InsertAccess, DefaultModifyAccess=T.UpdateAccess,DefaultDeleteAccess=T.DeleteAccess,DefaultPrintAccess=T.PrintAccess
				--FROM dbo.AutoGenerateTemplates AS AT INNER JOIN #TempC AS T ON AT.FormID=T.FormId WHERE AT.TemplateBaseId=@TemplateId
				
         COMMIT TRANSACTION
 END TRY
   BEGIN CATCH
            IF @@TRANCOUNT > 0
                ROLLBACK TRAN --RollBack in case of Error
				select ERROR_MESSAGE()
				DECLARE @ErrorMessage NVARCHAR(4000);  
				DECLARE @ErrorSeverity INT;  
				DECLARE @ErrorState INT;  

				SELECT   
				@ErrorMessage = ERROR_MESSAGE(),  
				@ErrorSeverity = ERROR_SEVERITY(),  
				@ErrorState = ERROR_STATE(); 
				RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState);
        END CATCH 
    END

GO

